+ * @param releasedByUserId 공개한 관리 계정. 공개 전이면 null
+ */
+public record LearningStage(
+        Long id,
+        StageKey stageKey,
+        int number,
+        String name,
+        String levelLabel,
+        String summary,
+        Instant releasedAt,
+        Long releasedByUserId) {
+
+    public LearningStage {
