+
+    /** 조각 수 상한. */
+    int maxRuns() default Integer.MAX_VALUE;
+
+    /** 허용하는 조각 종류. */
+    RunKind[] kinds() default {RunKind.TEXT, RunKind.TERM, RunKind.SOURCE};
+
+    String message() default "글자 조각이 올바르지 않습니다";
+
+    Class<?>[] groups() default {};
+
+    Class<? extends Payload>[] payload() default {};
+
